package com.primehr.succession.application;

import com.primehr.integration.administrative.AdministrativePositionTargetClient;
import com.primehr.shared.audit.PrimeHrAuditService;
import com.primehr.shared.exception.*;
import com.primehr.succession.api.SuccessionFoundationDtos.*;
import com.primehr.succession.api.SuccessionPlanningDtos.*;
import com.primehr.succession.domain.*;
import com.primehr.succession.infrastructure.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import java.util.function.Function;
import java.util.stream.Collectors;

@Service @Transactional
public class SuccessionPlanningServiceImpl implements SuccessionPlanningService {
 private final SuccessionCareerFamilyRepository familyRoots; private final SuccessionCareerFamilyVersionRepository families; private final SuccessionCareerPathLinkRepository links;
 private final SuccessionCriticalityFrameworkRepository frameworkRoots; private final SuccessionCriticalityFrameworkVersionRepository frameworks; private final SuccessionCriticalityCriterionRepository criteria;
 private final SuccessionCriticalPositionDesignationRepository designations; private final SuccessionCriticalityFindingRepository findings; private final SuccessionCommitteeCharterVersionRepository charters; private final SuccessionCommitteeMemberRepository members;
 private final AdministrativePositionTargetClient positions; private final PrimeHrAuditService audit;
 public SuccessionPlanningServiceImpl(SuccessionCareerFamilyRepository familyRoots,SuccessionCareerFamilyVersionRepository families,SuccessionCareerPathLinkRepository links,SuccessionCriticalityFrameworkRepository frameworkRoots,SuccessionCriticalityFrameworkVersionRepository frameworks,SuccessionCriticalityCriterionRepository criteria,SuccessionCriticalPositionDesignationRepository designations,SuccessionCriticalityFindingRepository findings,SuccessionCommitteeCharterVersionRepository charters,SuccessionCommitteeMemberRepository members,AdministrativePositionTargetClient positions,PrimeHrAuditService audit){this.familyRoots=familyRoots;this.families=families;this.links=links;this.frameworkRoots=frameworkRoots;this.frameworks=frameworks;this.criteria=criteria;this.designations=designations;this.findings=findings;this.charters=charters;this.members=members;this.positions=positions;this.audit=audit;}

 @Override @Transactional(readOnly=true) public List<CareerFamilyResponse> careerFamilies(String a){return families.findByAgencyIdOrderByCreatedAtDesc(a).stream().map(v->familyResponse(a,v)).toList();}
 @Override @Transactional(readOnly=true) public CareerFamilyResponse getCareerFamily(String a,String id){return familyResponse(a,family(a,id));}
 @Override public CareerFamilyResponse createCareerFamily(String a,CareerFamilyInput i,String c){requireNew(i.recordVersion());if(familyRoots.existsByAgencyIdAndNormalizedCode(a,norm(i.code())))throw new IllegalArgumentException("Career family code already exists");var root=familyRoots.saveAndFlush(new SuccessionCareerFamily(a,i.code()));var v=families.saveAndFlush(new SuccessionCareerFamilyVersion(a,root.getId(),1,null,i.title(),i.description(),i.legalBasis(),i.pathwayGuidance()));var out=familyResponse(a,v);record(a,"CREATE_SUCCESSION_CAREER_FAMILY","SUCCESSION_CAREER_FAMILY_VERSION",v,null,out,null,c);return out;}
 @Override public CareerFamilyResponse updateCareerFamily(String a,String id,CareerFamilyInput i,String c){var v=family(a,id);requireVersion(v.getVersion(),i.recordVersion());stable(familyRoot(a,v.getFamilyId()).getCode(),i.code());var before=familyResponse(a,v);v.update(i.title(),i.description(),i.legalBasis(),i.pathwayGuidance());families.saveAndFlush(v);var out=familyResponse(a,v);record(a,"UPDATE_SUCCESSION_CAREER_FAMILY","SUCCESSION_CAREER_FAMILY_VERSION",v,before,out,null,c);return out;}
 @Override public CareerFamilyResponse replacePathLinks(String a,String id,PathLinksInput i,String token,String c){var v=family(a,id);requireVersion(v.getVersion(),i.recordVersion());validateLinks(i.links());var before=familyResponse(a,v);var resolved=i.links().stream().map(x->new SuccessionCareerPathLink(a,id,positions.get(x.sourceType(),x.sourceId(),token),positions.get(x.targetType(),x.targetId(),token),x.relationshipType(),x.developmentGuidance(),x.displayOrder())).toList();links.deleteByAgencyIdAndFamilyVersionId(a,id);links.flush();links.saveAll(resolved);v.linksChanged();families.saveAndFlush(v);var out=familyResponse(a,v);record(a,"REPLACE_SUCCESSION_CAREER_PATHS","SUCCESSION_CAREER_FAMILY_VERSION",v,before,out,null,c);return out;}
 @Override public CareerFamilyResponse reviseCareerFamily(String a,String id,Transition i,String c){var p=family(a,id);requireVersion(p.getVersion(),i.recordVersion());published(p);int next=families.findByAgencyIdAndFamilyIdOrderByDefinitionVersionDesc(a,p.getFamilyId()).stream().mapToInt(SuccessionCareerFamilyVersion::getDefinitionVersion).max().orElse(0)+1;var v=families.saveAndFlush(new SuccessionCareerFamilyVersion(a,p.getFamilyId(),next,p.getId(),p.getTitle(),p.getDescription(),p.getLegalBasis(),p.getPathwayGuidance()));var old=links.findByAgencyIdAndFamilyVersionIdOrderByDisplayOrder(a,id);if(!old.isEmpty()){links.saveAll(old.stream().map(x->new SuccessionCareerPathLink(a,v.getId(),positionsFrom(x,true),positionsFrom(x,false),x.getRelationshipType(),x.getDevelopmentGuidance(),x.getDisplayOrder())).toList());v.linksChanged();families.saveAndFlush(v);}var out=familyResponse(a,v);record(a,"REVISE_SUCCESSION_CAREER_FAMILY","SUCCESSION_CAREER_FAMILY_VERSION",v,null,out,i.reason(),c);return out;}
 @Override public CareerFamilyResponse publishCareerFamily(String a,String id,Publish i,String token,String c){var v=family(a,id);requireVersion(v.getVersion(),i.recordVersion());var xs=links.findByAgencyIdAndFamilyVersionIdOrderByDisplayOrder(a,id);if(xs.isEmpty())throw new IllegalArgumentException("Career family requires at least one pathway");for(var x:xs){if(!x.getSourceFingerprint().equals(positions.get(x.getSourceTargetType(),x.getSourceTargetId(),token).sourceFingerprint())||!x.getTargetFingerprint().equals(positions.get(x.getTargetTargetType(),x.getTargetTargetId(),token).sourceFingerprint()))throw new OptimisticConflictException("Administrative position data changed; refresh career pathways before publication");}var prior=v.getSupersedesId()==null?null:family(a,v.getSupersedesId());validatePublish(i,prior,families.findByAgencyIdAndStatus(a,SuccessionDefinitionStatus.PUBLISHED),v.getId());var before=familyResponse(a,v);publish(v,prior,i,families);var out=familyResponse(a,v);record(a,"PUBLISH_SUCCESSION_CAREER_FAMILY","SUCCESSION_CAREER_FAMILY_VERSION",v,before,out,i.reason(),c);return out;}
 @Override public CareerFamilyResponse retireCareerFamily(String a,String id,Transition i,String c){var v=family(a,id);requireVersion(v.getVersion(),i.recordVersion());var before=familyResponse(a,v);v.retire(audit.currentActor(),i.reason(),Instant.now());families.saveAndFlush(v);var out=familyResponse(a,v);record(a,"RETIRE_SUCCESSION_CAREER_FAMILY","SUCCESSION_CAREER_FAMILY_VERSION",v,before,out,i.reason(),c);return out;}

 @Override @Transactional(readOnly=true) public List<FrameworkResponse> frameworks(String a){return frameworks.findByAgencyIdOrderByCreatedAtDesc(a).stream().map(v->frameworkResponse(a,v)).toList();}
 @Override @Transactional(readOnly=true) public FrameworkResponse getFramework(String a,String id){return frameworkResponse(a,framework(a,id));}
 @Override public FrameworkResponse createFramework(String a,FrameworkInput i,String c){requireNew(i.recordVersion());if(frameworkRoots.existsByAgencyIdAndNormalizedCode(a,norm(i.code())))throw new IllegalArgumentException("Criticality framework code already exists");var root=frameworkRoots.saveAndFlush(new SuccessionCriticalityFramework(a,i.code()));var v=frameworks.saveAndFlush(new SuccessionCriticalityFrameworkVersion(a,root.getId(),1,null,i.title(),i.description(),i.legalBasis(),i.decisionGuidance()));var out=frameworkResponse(a,v);record(a,"CREATE_SUCCESSION_CRITICALITY_FRAMEWORK","SUCCESSION_CRITICALITY_FRAMEWORK_VERSION",v,null,out,null,c);return out;}
 @Override public FrameworkResponse updateFramework(String a,String id,FrameworkInput i,String c){var v=framework(a,id);requireVersion(v.getVersion(),i.recordVersion());stable(frameworkRoot(a,v.getFrameworkId()).getCode(),i.code());var before=frameworkResponse(a,v);v.update(i.title(),i.description(),i.legalBasis(),i.decisionGuidance());frameworks.saveAndFlush(v);var out=frameworkResponse(a,v);record(a,"UPDATE_SUCCESSION_CRITICALITY_FRAMEWORK","SUCCESSION_CRITICALITY_FRAMEWORK_VERSION",v,before,out,null,c);return out;}
 @Override public FrameworkResponse replaceCriteria(String a,String id,CriteriaInput i,String c){var v=framework(a,id);requireVersion(v.getVersion(),i.recordVersion());validateCriteria(i.criteria());var before=frameworkResponse(a,v);criteria.deleteByAgencyIdAndFrameworkVersionId(a,id);criteria.flush();criteria.saveAll(i.criteria().stream().map(x->new SuccessionCriticalityCriterion(a,id,x.code(),x.label(),x.description(),x.evidenceGuidance(),x.displayOrder())).toList());v.criteriaChanged();frameworks.saveAndFlush(v);var out=frameworkResponse(a,v);record(a,"REPLACE_SUCCESSION_CRITICALITY_CRITERIA","SUCCESSION_CRITICALITY_FRAMEWORK_VERSION",v,before,out,null,c);return out;}
 @Override public FrameworkResponse reviseFramework(String a,String id,Transition i,String c){var p=framework(a,id);requireVersion(p.getVersion(),i.recordVersion());published(p);int next=frameworks.findByAgencyIdAndFrameworkIdOrderByDefinitionVersionDesc(a,p.getFrameworkId()).stream().mapToInt(SuccessionCriticalityFrameworkVersion::getDefinitionVersion).max().orElse(0)+1;var v=frameworks.saveAndFlush(new SuccessionCriticalityFrameworkVersion(a,p.getFrameworkId(),next,p.getId(),p.getTitle(),p.getDescription(),p.getLegalBasis(),p.getDecisionGuidance()));var old=criteria.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(a,id);if(!old.isEmpty()){criteria.saveAll(old.stream().map(x->new SuccessionCriticalityCriterion(a,v.getId(),x.getCode(),x.getLabel(),x.getDescription(),x.getEvidenceGuidance(),x.getDisplayOrder())).toList());v.criteriaChanged();frameworks.saveAndFlush(v);}var out=frameworkResponse(a,v);record(a,"REVISE_SUCCESSION_CRITICALITY_FRAMEWORK","SUCCESSION_CRITICALITY_FRAMEWORK_VERSION",v,null,out,i.reason(),c);return out;}
 @Override public FrameworkResponse publishFramework(String a,String id,Publish i,String c){var v=framework(a,id);requireVersion(v.getVersion(),i.recordVersion());if(criteria.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(a,id).isEmpty())throw new IllegalArgumentException("Criticality framework requires criteria");var prior=v.getSupersedesId()==null?null:framework(a,v.getSupersedesId());validatePublish(i,prior,frameworks.findByAgencyIdAndStatus(a,SuccessionDefinitionStatus.PUBLISHED),v.getId());var before=frameworkResponse(a,v);publish(v,prior,i,frameworks);var out=frameworkResponse(a,v);record(a,"PUBLISH_SUCCESSION_CRITICALITY_FRAMEWORK","SUCCESSION_CRITICALITY_FRAMEWORK_VERSION",v,before,out,i.reason(),c);return out;}
 @Override public FrameworkResponse retireFramework(String a,String id,Transition i,String c){var v=framework(a,id);requireVersion(v.getVersion(),i.recordVersion());var before=frameworkResponse(a,v);v.retire(audit.currentActor(),i.reason(),Instant.now());frameworks.saveAndFlush(v);var out=frameworkResponse(a,v);record(a,"RETIRE_SUCCESSION_CRITICALITY_FRAMEWORK","SUCCESSION_CRITICALITY_FRAMEWORK_VERSION",v,before,out,i.reason(),c);return out;}

 @Override @Transactional(readOnly=true) public List<DesignationResponse> designations(String a,String actor,boolean assignedOnly){return designations.findByAgencyIdOrderByCreatedAtDesc(a).stream().filter(v->!assignedOnly||activeMember(a,v.getCharterVersionId(),actor,v.getAssessmentDate())).map(v->designationResponse(a,v)).toList();}
 @Override @Transactional(readOnly=true) public DesignationResponse getDesignation(String a,String id,String actor,boolean assignedOnly){var v=designation(a,id);if(assignedOnly&&!activeMember(a,v.getCharterVersionId(),actor,v.getAssessmentDate()))throw new AccessDeniedException("Designation is not assigned to the current committee member");return designationResponse(a,v);}
 @Override public DesignationResponse createDesignation(String a,DesignationInput i,String token,String c){requireNew(i.recordVersion());if(designations.existsByAgencyIdAndTargetTypeAndTargetIdAndStatusIn(a,i.targetType(),i.targetId(),List.of(SuccessionCriticalPositionDesignation.Status.DRAFT,SuccessionCriticalPositionDesignation.Status.SUBMITTED,SuccessionCriticalPositionDesignation.Status.APPROVED)))throw new IllegalArgumentException("An active designation already exists for this position target");var f=framework(a,i.frameworkVersionId());effectivePublished(f,i.assessmentDate(),"Criticality framework");var ch=charter(a,i.charterVersionId());effectivePublished(ch,i.assessmentDate(),"Committee charter");var target=positions.get(i.targetType(),i.targetId(),token);var v=designations.saveAndFlush(new SuccessionCriticalPositionDesignation(a,target,f.getId(),f.getDefinitionVersion(),frameworkFingerprint(f),ch.getId(),i.title(),i.justification(),i.assessmentDate(),i.reviewDate()));replaceFindings(a,v,f,i.findings());var out=designationResponse(a,v);audit.record(a,"CREATE_CRITICAL_POSITION_DESIGNATION","SUCCESSION_CRITICAL_POSITION",v.getId(),null,v.getVersion(),null,out,null,c);return out;}
 @Override public DesignationResponse updateDesignation(String a,String id,DesignationInput i,String token,String c){var v=designation(a,id);requireVersion(v.getVersion(),i.recordVersion());if(v.getTargetType()!=i.targetType()||!v.getTargetId().equals(i.targetId())||!v.getFrameworkVersionId().equals(i.frameworkVersionId())||!v.getCharterVersionId().equals(i.charterVersionId()))throw new IllegalArgumentException("Position, framework, and committee are immutable; create a new designation");var current=positions.get(i.targetType(),i.targetId(),token);if(!v.getSourceFingerprint().equals(current.sourceFingerprint()))throw new OptimisticConflictException("Administrative position data changed; create a refreshed designation");var before=designationResponse(a,v);v.update(i.title(),i.justification(),i.assessmentDate(),i.reviewDate());replaceFindings(a,v,framework(a,v.getFrameworkVersionId()),i.findings());designations.saveAndFlush(v);var out=designationResponse(a,v);audit.record(a,"UPDATE_CRITICAL_POSITION_DESIGNATION","SUCCESSION_CRITICAL_POSITION",v.getId(),null,v.getVersion(),before,out,null,c);return out;}
 @Override public DesignationResponse submitDesignation(String a,String id,Transition i,String token,String c){var v=designation(a,id);requireVersion(v.getVersion(),i.recordVersion());var current=positions.get(v.getTargetType(),v.getTargetId(),token);if(!v.getSourceFingerprint().equals(current.sourceFingerprint()))throw new OptimisticConflictException("Administrative position data changed; refresh designation before submission");var f=framework(a,v.getFrameworkVersionId());effectivePublished(f,v.getAssessmentDate(),"Criticality framework");var ch=charter(a,v.getCharterVersionId());effectivePublished(ch,v.getAssessmentDate(),"Committee charter");validateFindingCompleteness(a,v.getId(),f.getId());var before=designationResponse(a,v);v.submit(audit.currentActor(),Instant.now());designations.saveAndFlush(v);var out=designationResponse(a,v);audit.record(a,"SUBMIT_CRITICAL_POSITION_DESIGNATION","SUCCESSION_CRITICAL_POSITION",v.getId(),null,v.getVersion(),before,out,i.reason(),c);return out;}
 @Override public DesignationResponse approveDesignation(String a,String id,DesignationDecision i,String c){var v=designation(a,id);requireVersion(v.getVersion(),i.recordVersion());requireActiveMember(a,v.getCharterVersionId(),audit.currentActor(),LocalDate.now(ZoneId.of("Asia/Manila")));var before=designationResponse(a,v);v.approve(audit.currentActor(),i.reason(),i.effectiveFrom(),i.effectiveTo(),Instant.now());designations.saveAndFlush(v);var out=designationResponse(a,v);audit.record(a,"APPROVE_CRITICAL_POSITION_DESIGNATION","SUCCESSION_CRITICAL_POSITION",v.getId(),null,v.getVersion(),before,out,i.reason(),c);return out;}
 @Override public DesignationResponse rejectDesignation(String a,String id,DesignationDecision i,String c){var v=designation(a,id);requireVersion(v.getVersion(),i.recordVersion());requireActiveMember(a,v.getCharterVersionId(),audit.currentActor(),LocalDate.now(ZoneId.of("Asia/Manila")));var before=designationResponse(a,v);v.reject(audit.currentActor(),i.reason(),Instant.now());designations.saveAndFlush(v);var out=designationResponse(a,v);audit.record(a,"REJECT_CRITICAL_POSITION_DESIGNATION","SUCCESSION_CRITICAL_POSITION",v.getId(),null,v.getVersion(),before,out,i.reason(),c);return out;}
 @Override public DesignationResponse retireDesignation(String a,String id,DesignationDecision i,String c){var v=designation(a,id);requireVersion(v.getVersion(),i.recordVersion());var before=designationResponse(a,v);v.retire(audit.currentActor(),i.reason(),Instant.now());designations.saveAndFlush(v);var out=designationResponse(a,v);audit.record(a,"RETIRE_CRITICAL_POSITION_DESIGNATION","SUCCESSION_CRITICAL_POSITION",v.getId(),null,v.getVersion(),before,out,i.reason(),c);return out;}

 private void replaceFindings(String a,SuccessionCriticalPositionDesignation v,SuccessionCriticalityFrameworkVersion f,List<FindingInput> inputs){var cs=criteria.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(a,f.getId());var byId=cs.stream().collect(Collectors.toMap(SuccessionCriticalityCriterion::getId,Function.identity()));if(inputs.size()!=cs.size()||inputs.stream().map(FindingInput::criterionId).distinct().count()!=cs.size()||inputs.stream().anyMatch(x->!byId.containsKey(x.criterionId())))throw new IllegalArgumentException("Exactly one finding is required for every framework criterion");findings.deleteByAgencyIdAndDesignationId(a,v.getId());findings.flush();findings.saveAll(inputs.stream().map(x->new SuccessionCriticalityFinding(a,v.getId(),byId.get(x.criterionId()),x.outcome(),x.reason(),x.evidenceReference())).toList());}
 private void validateFindingCompleteness(String a,String id,String frameworkId){int expected=criteria.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(a,frameworkId).size();if(expected==0||findings.findByAgencyIdAndDesignationIdOrderByDisplayOrder(a,id).size()!=expected)throw new IllegalArgumentException("Designation findings are incomplete");}
 private void validateLinks(List<PathLinkInput> xs){Set<String> keys=new HashSet<>();Set<Integer> orders=new HashSet<>();for(var x:xs){String k=x.sourceType()+":"+x.sourceId()+":"+x.targetType()+":"+x.targetId()+":"+x.relationshipType();if(!keys.add(k)||!orders.add(x.displayOrder()))throw new IllegalArgumentException("Career pathways and display order must be unique");}}
 private void validateCriteria(List<CriterionInput> xs){Set<String> codes=new HashSet<>();Set<Integer> orders=new HashSet<>();for(var x:xs)if(!codes.add(norm(x.code()))||!orders.add(x.displayOrder()))throw new IllegalArgumentException("Criterion codes and display order must be unique");}
 private boolean activeMember(String a,String charterId,String actor,LocalDate on){return members.findByAgencyIdAndCharterVersionIdOrderByMemberRole(a,charterId).stream().anyMatch(m->m.getEmployeeNo().equalsIgnoreCase(actor)&&!on.isBefore(m.getEffectiveFrom())&&(m.getEffectiveTo()==null||!on.isAfter(m.getEffectiveTo())));}
 private void requireActiveMember(String a,String charterId,String actor,LocalDate on){if(!activeMember(a,charterId,actor,on))throw new AccessDeniedException("Only an active member of the bound succession committee may decide this designation");}
 private static void effectivePublished(SuccessionVersionedDefinition v,LocalDate on,String label){if(!v.effectiveOn(on))throw new IllegalArgumentException(label+" must be published and effective on the assessment date");}
 private static String frameworkFingerprint(SuccessionCriticalityFrameworkVersion f){return f.getId()+":"+f.getDefinitionVersion()+":"+f.getCriteriaRevision();}
 private static com.primehr.integration.administrative.AdministrativePositionTarget positionsFrom(SuccessionCareerPathLink x,boolean source){return source?new com.primehr.integration.administrative.AdministrativePositionTarget(x.getSourceTargetType(),x.getSourceTargetId(),x.getSourceJobPositionId(),x.getSourcePositionName(),null,null,x.getSourcePlantillaId(),x.getSourcePlantillaName(),x.getSourceFingerprint(),x.getSourceFetchedAt()):new com.primehr.integration.administrative.AdministrativePositionTarget(x.getTargetTargetType(),x.getTargetTargetId(),x.getTargetJobPositionId(),x.getTargetPositionName(),null,null,x.getTargetPlantillaId(),x.getTargetPlantillaName(),x.getTargetFingerprint(),x.getTargetFetchedAt());}
 private CareerFamilyResponse familyResponse(String a,SuccessionCareerFamilyVersion v){return new CareerFamilyResponse(v.getId(),v.getFamilyId(),familyRoot(a,v.getFamilyId()).getCode(),v.getTitle(),v.getDescription(),v.getLegalBasis(),v.getPathwayGuidance(),v.getLinksRevision(),v.getDefinitionVersion(),v.getSupersedesId(),v.getStatus().name(),v.getEffectiveFrom(),v.getEffectiveTo(),v.getVersion(),links.findByAgencyIdAndFamilyVersionIdOrderByDisplayOrder(a,v.getId()).stream().map(x->new PathLinkResponse(x.getId(),x.getSourceTargetType().name(),x.getSourceTargetId(),x.getSourcePositionName(),x.getSourcePlantillaId(),x.getSourcePlantillaName(),x.getTargetTargetType().name(),x.getTargetTargetId(),x.getTargetPositionName(),x.getTargetPlantillaId(),x.getTargetPlantillaName(),x.getRelationshipType().name(),x.getDevelopmentGuidance(),x.getDisplayOrder())).toList());}
 private FrameworkResponse frameworkResponse(String a,SuccessionCriticalityFrameworkVersion v){return new FrameworkResponse(v.getId(),v.getFrameworkId(),frameworkRoot(a,v.getFrameworkId()).getCode(),v.getTitle(),v.getDescription(),v.getLegalBasis(),v.getDecisionGuidance(),v.getCriteriaRevision(),v.getDefinitionVersion(),v.getSupersedesId(),v.getStatus().name(),v.getEffectiveFrom(),v.getEffectiveTo(),v.getVersion(),criteria.findByAgencyIdAndFrameworkVersionIdOrderByDisplayOrder(a,v.getId()).stream().map(x->new CriterionResponse(x.getId(),x.getCode(),x.getLabel(),x.getDescription(),x.getEvidenceGuidance(),x.getDisplayOrder())).toList());}
 private DesignationResponse designationResponse(String a,SuccessionCriticalPositionDesignation v){return new DesignationResponse(v.getId(),v.getTargetType().name(),v.getTargetId(),v.getJobPositionId(),v.getPositionName(),v.getPlantillaId(),v.getPlantillaName(),v.getFrameworkVersionId(),v.getFrameworkDefinitionVersion(),v.getCharterVersionId(),v.getTitle(),v.getJustification(),v.getAssessmentDate(),v.getEffectiveFrom(),v.getEffectiveTo(),v.getReviewDate(),v.getStatus().name(),v.getSubmittedBy(),v.getSubmittedAt(),v.getDecisionBy(),v.getDecisionAt(),v.getDecisionReason(),v.getVersion(),findings.findByAgencyIdAndDesignationIdOrderByDisplayOrder(a,v.getId()).stream().map(x->new FindingResponse(x.getId(),x.getCriterionId(),x.getCriterionCode(),x.getCriterionLabel(),x.getOutcome().name(),x.getReason(),x.getEvidenceReference(),x.getDisplayOrder())).toList());}
 private SuccessionCareerFamilyVersion family(String a,String id){return families.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Career family not found"));} private SuccessionCareerFamily familyRoot(String a,String id){return familyRoots.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Career family root not found"));}
 private SuccessionCriticalityFrameworkVersion framework(String a,String id){return frameworks.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Criticality framework not found"));} private SuccessionCriticalityFramework frameworkRoot(String a,String id){return frameworkRoots.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Criticality framework root not found"));}
 private SuccessionCommitteeCharterVersion charter(String a,String id){return charters.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Committee charter not found"));} private SuccessionCriticalPositionDesignation designation(String a,String id){return designations.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Critical position designation not found"));}
 private static void requireNew(Long v){if(v!=null)throw new IllegalArgumentException("recordVersion must be omitted for new records");} private static void requireVersion(long current,Long supplied){if(supplied==null||current!=supplied)throw new OptimisticConflictException("Record version is stale");} private static void stable(String a,String b){if(!norm(a).equals(norm(b)))throw new IllegalArgumentException("Definition code cannot change");} private static void published(SuccessionVersionedDefinition v){if(v.getStatus()!=SuccessionDefinitionStatus.PUBLISHED)throw new IllegalLifecycleTransitionException("Only published definitions may be revised");} private static String norm(String x){return x==null?"":x.trim().toUpperCase(Locale.ROOT);}
 private <T extends SuccessionVersionedDefinition> void validatePublish(Publish i,T prior,List<T> existing,String id){if(prior==null&&existing.stream().anyMatch(x->!x.getId().equals(id)))throw new IllegalLifecycleTransitionException("A published definition already exists; create a revision");if(prior!=null&&!i.effectiveFrom().isAfter(prior.getEffectiveFrom()))throw new IllegalArgumentException("Revision effectivity must follow predecessor");}
 private <T extends SuccessionVersionedDefinition> void publish(T v,T prior,Publish i,org.springframework.data.jpa.repository.JpaRepository<T,String> repo){Instant now=Instant.now();v.publish(i.effectiveFrom(),i.effectiveTo(),audit.currentActor(),now);repo.saveAndFlush(v);if(prior!=null){prior.supersede(i.effectiveFrom(),audit.currentActor(),now);repo.saveAndFlush(prior);}}
 private void record(String a,String action,String type,SuccessionVersionedDefinition v,Object before,Object after,String reason,String c){audit.record(a,action,type,v.getId(),v.getDefinitionVersion(),v.getVersion(),before,after,reason,c);}
}
